INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('19', 'mzm', 'Mazmur', 150, 1, 'Haleluya! Pujilah Allah dalam tempat kudus-Nya! Pujilah Dia dalam cakrawala-Nya yang kuat!', 'id', 'TB'),
  ('19', 'mzm', 'Mazmur', 150, 2, 'Pujilah Dia karena segala keperkasaan-Nya, pujilah Dia sesuai dengan kebesaran-Nya yang hebat!', 'id', 'TB'),
  ('19', 'mzm', 'Mazmur', 150, 3, 'Pujilah Dia dengan tiupan sangkakala, pujilah Dia dengan gambus dan kecapi!', 'id', 'TB'),
  ('19', 'mzm', 'Mazmur', 150, 4, 'Pujilah Dia dengan rebana dan tari-tarian, pujilah Dia dengan permainan kecapi dan seruling!', 'id', 'TB'),
  ('19', 'mzm', 'Mazmur', 150, 5, 'Pujilah Dia dengan ceracap yang berdenting, pujilah Dia dengan ceracap yang berdentang!', 'id', 'TB'),
  ('19', 'mzm', 'Mazmur', 150, 6, 'Biarlah segala yang bernafas memuji TUHAN! Haleluya!', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 1, 'Amsal-amsal Salomo bin Daud, raja Israel,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 2, 'untuk mengetahui hikmat dan didikan, untuk mengerti kata-kata yang bermakna,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 3, 'untuk menerima didikan yang menjadikan pandai, serta kebenaran, keadilan dan kejujuran,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 4, 'untuk memberikan kecerdasan kepada orang yang tak berpengalaman, dan pengetahuan serta kebijaksanaan kepada orang muda?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 5, 'baiklah orang bijak mendengar dan menambah ilmu dan baiklah orang yang berpengertian memperoleh bahan pertimbangan?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 6, 'untuk mengerti amsal dan ibarat, perkataan dan teka-teki orang bijak.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 7, 'Takut akan TUHAN adalah permulaan pengetahuan, tetapi orang bodoh menghina hikmat dan didikan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 8, 'Hai anakku, dengarkanlah didikan ayahmu, dan jangan menyia-nyiakan ajaran ibumu', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 9, 'sebab karangan bunga yang indah itu bagi kepalamu, dan suatu kalung bagi lehermu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 10, 'Hai anakku, jikalau orang berdosa hendak membujuk engkau, janganlah engkau menurut;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 11, 'jikalau mereka berkata: "Marilah ikut kami, biarlah kita menghadang darah, biarlah kita mengintai orang yang tidak bersalah, dengan tidak semena-mena;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 12, 'biarlah kita menelan mereka hidup-hidup seperti dunia orang mati, bulat-bulat, seperti mereka yang turun ke liang kubur;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 13, 'kita akan mendapat pelbagai benda yang berharga, kita akan memenuhi rumah kita dengan barang rampasan;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 14, 'buanglah undimu ke tengah-tengah kami, satu pundi-pundi bagi kita sekalian."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 15, 'Hai anakku, janganlah engkau hidup menurut tingkah laku mereka, tahanlah kakimu dari pada jalan mereka,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 16, 'karena kaki mereka lari menuju kejahatan dan bergegas-gegas untuk menumpahkan darah.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 17, 'Sebab percumalah jaring dibentangkan di depan mata segala yang bersayap,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 18, 'padahal mereka menghadang darahnya sendiri dan mengintai nyawanya sendiri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 19, 'Demikianlah pengalaman setiap orang yang loba akan keuntungan gelap, yang mengambil nyawa orang yang mempunyainya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 20, 'Hikmat berseru nyaring di jalan-jalan, di lapangan-lapangan ia memperdengarkan suaranya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 21, 'di atas tembok-tembok ia berseru-seru, di depan pintu-pintu gerbang kota ia mengucapkan kata-katanya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 22, '"Berapa lama lagi, hai orang yang tak berpengalaman, kamu masih cinta kepada keadaanmu itu, pencemooh masih gemar kepada cemooh, dan orang bebal benci kepada pengetahuan?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 23, 'Berpalinglah kamu kepada teguranku! Sesungguhnya, aku hendak mencurahkan isi hatiku kepadamu dan memberitahukan perkataanku kepadamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 24, 'Oleh karena kamu menolak ketika aku memanggil, dan tidak ada orang yang menghiraukan ketika aku mengulurkan tanganku,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 25, 'bahkan, kamu mengabaikan nasihatku, dan tidak mau menerima teguranku,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 26, 'maka aku juga akan menertawakan celakamu; aku akan berolok-olok, apabila kedahsyatan datang ke atasmu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 27, 'apabila kedahsyatan datang ke atasmu seperti badai, dan celaka melanda kamu seperti angin puyuh, apabila kesukaran dan kecemasan datang menimpa kamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 28, 'Pada waktu itu mereka akan berseru kepadaku, tetapi tidak akan kujawab, mereka akan bertekun mencari aku, tetapi tidak akan menemukan aku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 29, 'Oleh karena mereka benci kepada pengetahuan dan tidak memilih takut akan TUHAN,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 30, 'tidak mau menerima nasihatku, tetapi menolak segala teguranku,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 31, 'maka mereka akan memakan buah perbuatan mereka, dan menjadi kenyang oleh rencana mereka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 32, 'Sebab orang yang tak berpengalaman akan dibunuh oleh keengganannya, dan orang bebal akan dibinasakan oleh kelalaiannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 1, 33, 'Tetapi siapa mendengarkan aku, ia akan tinggal dengan aman, terlindung dari pada kedahsyatan malapetaka."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 1, 'Hai anakku, jikalau engkau menerima perkataanku dan menyimpan perintahku di dalam hatimu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 2, 'sehingga telingamu memperhatikan hikmat, dan engkau mencenderungkan hatimu kepada kepandaian,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 3, 'ya, jikalau engkau berseru kepada pengertian, dan menujukan suaramu kepada kepandaian,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 4, 'jikalau engkau mencarinya seperti mencari perak, dan mengejarnya seperti mengejar harta terpendam,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 5, 'maka engkau akan memperoleh pengertian tentang takut akan TUHAN dan mendapat pengenalan akan Allah.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 6, 'Karena Tuhanlah yang memberikan hikmat, dari mulut-Nya datang pengetahuan dan kepandaian.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 7, 'Ia menyediakan pertolongan bagi orang yang jujur, menjadi perisai bagi orang yang tidak bercela lakunya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 8, 'sambil menjaga jalan keadilan, dan memelihara jalan orang-orang-Nya yang setia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 9, 'Maka engkau akan mengerti tentang kebenaran, keadilan, dan kejujuran, bahkan setiap jalan yang baik.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 10, 'Karena hikmat akan masuk ke dalam hatimu dan pengetahuan akan menyenangkan jiwamu;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 11, 'kebijaksanaan akan memelihara engkau, kepandaian akan menjaga engkau', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 12, 'supaya engkau terlepas dari jalan yang jahat, dari orang yang mengucapkan tipu muslihat,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 13, 'dari mereka yang meninggalkan jalan yang lurus dan menempuh jalan yang gelap;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 14, 'yang bersukacita melakukan kejahatan, bersorak-sorak karena tipu muslihat yang jahat,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 15, 'yang berliku-liku jalannya dan yang sesat perilakunya;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 16, 'supaya engkau terlepas dari perempuan jalang, dari perempuan yang asing, yang licin perkataannya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 17, 'yang meninggalkan teman hidup masa mudanya dan melupakan perjanjian Allahnya;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 18, 'sesungguhnya rumahnya hilang tenggelam ke dalam maut, jalannya menuju ke arwah-arwah.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 19, 'Segala orang yang datang kepadanya tidak balik kembali, dan tidak mencapai jalan kehidupan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 20, 'Sebab itu tempuhlah jalan orang baik, dan peliharalah jalan-jalan orang benar.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 21, 'Karena orang jujurlah akan mendiami tanah, dan orang yang tak bercelalah yang akan tetap tinggal di situ,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 2, 22, 'tetapi orang fasik akan dipunahkan dari tanah itu, dan pengkhianat akan dibuang dari situ.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 1, 'Hai anakku, janganlah engkau melupakan ajaranku, dan biarlah hatimu memelihara perintahku,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 2, 'karena panjang umur dan lanjut usia serta sejahtera akan ditambahkannya kepadamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 3, 'Janganlah kiranya kasih dan setia meninggalkan engkau! Kalungkanlah itu pada lehermu, tuliskanlah itu pada loh hatimu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 4, 'maka engkau akan mendapat kasih dan penghargaan dalam pandangan Allah serta manusia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 5, 'Percayalah kepada TUHAN dengan segenap hatimu, dan janganlah bersandar kepada pengertianmu sendiri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 6, 'Akuilah Dia dalam segala lakumu, maka Ia akan meluruskan jalanmu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 7, 'Janganlah engkau menganggap dirimu sendiri bijak, takutlah akan TUHAN dan jauhilah kejahatan;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 8, 'itulah yang akan menyembuhkan tubuhmu dan menyegarkan tulang-tulangmu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 9, 'Muliakanlah TUHAN dengan hartamu dan dengan hasil pertama dari segala penghasilanmu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 10, 'maka lumbung-lumbungmu akan diisi penuh sampai melimpah-limpah, dan bejana pemerahanmu akan meluap dengan air buah anggurnya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 11, 'Hai anakku, janganlah engkau menolak didikan TUHAN, dan janganlah engkau bosan akan peringatan-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 12, 'Karena TUHAN memberi ajaran kepada yang dikasihi-Nya, seperti seorang ayah kepada anak yang disayangi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 13, 'Berbahagialah orang yang mendapat hikmat, orang yang memperoleh kepandaian,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 14, 'karena keuntungannya melebihi keuntungan perak, dan hasilnya melebihi emas.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 15, 'Ia lebih berharga dari pada permata; apapun yang kauinginkan, tidak dapat menyamainya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 16, 'Umur panjang ada di tangan kanannya, di tangan kirinya kekayaan dan kehormatan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 17, 'Jalannya adalah jalan penuh bahagia, segala jalannya sejahtera semata-mata.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 18, 'Ia menjadi pohon kehidupan bagi orang yang memegangnya, siapa yang berpegang padanya akan disebut berbahagia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 19, 'Dengan hikmat TUHAN telah meletakkan dasar bumi, dengan pengertian ditetapkan-Nya langit,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 20, 'dengan pengetahuan-Nya air samudera raya berpencaran dan awan menitikkan embun.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 21, 'Hai anakku, janganlah pertimbangan dan kebijaksanaan itu menjauh dari matamu, peliharalah itu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 22, 'maka itu akan menjadi kehidupan bagi jiwamu, dan perhiasan bagi lehermu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 23, 'Maka engkau akan berjalan di jalanmu dengan aman, dan kakimu tidak akan terantuk.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 24, 'Jikalau engkau berbaring, engkau tidak akan terkejut, tetapi engkau akan berbaring dan tidur nyenyak.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 25, 'Janganlah takut kepada kekejutan yang tiba-tiba, atau kepada kebinasaan orang fasik, bila itu datang.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 26, 'Karena Tuhanlah yang akan menjadi sandaranmu, dan akan menghindarkan kakimu dari jerat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 27, 'Janganlah menahan kebaikan dari pada orang-orang yang berhak menerimanya, padahal engkau mampu melakukannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 28, 'Janganlah engkau berkata kepada sesamamu: "Pergilah dan kembalilah, besok akan kuberi," sedangkan yang diminta ada padamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 29, 'Janganlah merencanakan kejahatan terhadap sesamamu, sedangkan tanpa curiga ia tinggal bersama-sama dengan engkau.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 30, 'Janganlah bertengkar tidak semena-mena dengan seseorang, jikalau ia tidak berbuat jahat kepadamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 31, 'Janganlah iri hati kepada orang yang melakukan kelaliman, dan janganlah memilih satupun dari jalannya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 32, 'karena orang yang sesat adalah kekejian bagi TUHAN, tetapi dengan orang jujur Ia bergaul erat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 33, 'Kutuk TUHAN ada di dalam rumah orang fasik, tetapi tempat kediaman orang benar diberkati-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 34, 'Apabila Ia menghadapi pencemooh, maka Iapun mencemooh, tetapi orang yang rendah hati dikasihani-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 3, 35, 'Orang yang bijak akan mewarisi kehormatan, tetapi orang yang bebal akan menerima cemooh.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 1, 'Dengarkanlah, hai anak-anak, didikan seorang ayah, dan perhatikanlah supaya engkau beroleh pengertian,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 2, 'karena aku memberikan ilmu yang baik kepadamu; janganlah meninggalkan petunjukku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 3, 'Karena ketika aku masih tinggal di rumah ayahku sebagai anak, lemah dan sebagai anak tunggal bagi ibuku,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 4, 'aku diajari ayahku, katanya kepadaku: "Biarlah hatimu memegang perkataanku; berpeganglah pada petunjuk-petunjukku, maka engkau akan hidup.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 5, 'Perolehlah hikmat, perolehlah pengertian, jangan lupa, dan jangan menyimpang dari perkataan mulutku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 6, 'Janganlah meninggalkan hikmat itu, maka engkau akan dipeliharanya, kasihilah dia, maka engkau akan dijaganya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 7, 'Permulaan hikmat ialah: perolehlah hikmat dan dengan segala yang kauperoleh perolehlah pengertian.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 8, 'Junjunglah dia, maka engkau akan ditinggikannya; engkau akan dijadikan terhormat, apabila engkau memeluknya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 9, 'Ia akan mengenakan karangan bunga yang indah di kepalamu, mahkota yang indah akan dikaruniakannya kepadamu."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 10, 'Hai anakku, dengarkanlah dan terimalah perkataanku, supaya tahun hidupmu menjadi banyak.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 11, 'Aku mengajarkan jalan hikmat kepadamu, aku memimpin engkau di jalan yang lurus.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 12, 'Bila engkau berjalan langkahmu tidak akan terhambat, bila engkau berlari engkau tidak akan tersandung.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 13, 'Berpeganglah pada didikan, janganlah melepaskannya, peliharalah dia, karena dialah hidupmu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 14, 'Janganlah menempuh jalan orang fasik, dan janganlah mengikuti jalan orang jahat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 15, 'Jauhilah jalan itu, janganlah melaluinya, menyimpanglah dari padanya dan jalanlah terus.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 16, 'Karena mereka tidak dapat tidur, bila tidak berbuat jahat; kantuk mereka lenyap, bila mereka tidak membuat orang tersandung;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 17, 'karena mereka makan roti kefasikan, dan minum anggur kelaliman.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 18, 'Tetapi jalan orang benar itu seperti cahaya fajar, yang kian bertambah terang sampai rembang tengah hari.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 19, 'Jalan orang fasik itu seperti kegelapan; mereka tidak tahu apa yang menyebabkan mereka tersandung.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 20, 'Hai anakku, perhatikanlah perkataanku, arahkanlah telingamu kepada ucapanku;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 21, 'janganlah semuanya itu menjauh dari matamu, simpanlah itu di lubuk hatimu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 22, 'Karena itulah yang menjadi kehidupan bagi mereka yang mendapatkannya dan kesembuhan bagi seluruh tubuh mereka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 23, 'Jagalah hatimu dengan segala kewaspadaan, karena dari situlah terpancar kehidupan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 24, 'Buanglah mulut serong dari padamu dan jauhkanlah bibir yang dolak-dalik dari padamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 25, 'Biarlah matamu memandang terus ke depan dan tatapan matamu tetap ke muka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 26, 'Tempuhlah jalan yang rata dan hendaklah tetap segala jalanmu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 4, 27, 'Janganlah menyimpang ke kanan atau ke kiri, jauhkanlah kakimu dari kejahatan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 1, 'Hai anakku, perhatikanlah hikmatku, arahkanlah telingamu kepada kepandaian yang kuajarkan,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 2, 'supaya engkau berpegang pada kebijaksanaan dan bibirmu memelihara pengetahuan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 3, 'Karena bibir perempuan jalang menitikkan tetesan madu dan langit-langit mulutnya lebih licin dari pada minyak,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 4, 'tetapi kemudian ia pahit seperti empedu, dan tajam seperti pedang bermata dua.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 5, 'Kakinya turun menuju maut, langkahnya menuju dunia orang mati.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 6, 'Ia tidak menempuh jalan kehidupan, jalannya sesat, tanpa diketahuinya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 7, 'Sebab itu, hai anak-anak, dengarkanlah aku, janganlah kamu menyimpang dari pada perkataan mulutku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 8, 'Jauhkanlah jalanmu dari pada dia, dan janganlah menghampiri pintu rumahnya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 9, 'supaya engkau jangan menyerahkan keremajaanmu kepada orang lain, dan tahun-tahun umurmu kepada orang kejam;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 10, 'supaya orang lain jangan mengenyangkan diri dengan kekayaanmu, dan hasil susah payahmu jangan masuk ke rumah orang yang tidak dikenal', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 11, 'dan pada akhirnya engkau akan mengeluh, kalau daging dan tubuhmu habis binasa,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 12, 'lalu engkau akan berkata: "Ah, mengapa aku benci kepada didikan, dan hatiku menolak teguran;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 13, 'mengapa aku tidak mendengarkan suara guru-guruku, dan tidak mengarahkan telingaku kepada pengajar-pengajarku?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 14, 'Aku nyaris terjerumus ke dalam tiap malapetaka di tengah-tengah jemaah dan perkumpulan."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 15, 'Minumlah air dari kulahmu sendiri, minumlah air dari sumurmu yang membual.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 16, 'Patutkah mata airmu meluap ke luar seperti batang-batang air ke lapangan-lapangan?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 17, 'Biarlah itu menjadi kepunyaanmu sendiri, jangan juga menjadi kepunyaan orang lain.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 18, 'Diberkatilah kiranya sendangmu, bersukacitalah dengan isteri masa mudamu:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 19, 'rusa yang manis, kijang yang jelita; biarlah buah dadanya selalu memuaskan engkau, dan engkau senantiasa berahi karena cintanya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 20, 'Hai anakku, mengapa engkau berahi akan perempuan jalang, dan mendekap dada perempuan asing?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 21, 'Karena segala jalan orang terbuka di depan mata TUHAN, dan segala langkah orang diawasi-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 22, 'Orang fasik tertangkap dalam kejahatannya, dan terjerat dalam tali dosanya sendiri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 5, 23, 'Ia mati, karena tidak menerima didikan dan karena kebodohannya yang besar ia tersesat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 1, 'Hai anakku, jikalau engkau menjadi penanggung sesamamu, dan membuat persetujuan dengan orang lain;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 2, 'jikalau engkau terjerat dalam perkataan mulutmu, tertangkap dalam perkataan mulutmu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 3, 'buatlah begini, hai anakku, dan lepaskanlah dirimu, karena engkau telah jatuh ke dalam genggaman sesamamu: pergilah, berlututlah, dan desaklah sesamamu itu;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 4, 'janganlah membiarkan matamu tidur, dan kelopak matamu mengantuk;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 5, 'lepaskanlah dirimu seperti kijang dari pada tangkapan, seperti burung dari pada tangan pemikat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 6, 'Hai pemalas, pergilah kepada semut, perhatikanlah lakunya dan jadilah bijak:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 7, 'biarpun tidak ada pemimpinnya, pengaturnya atau penguasanya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 8, 'ia menyediakan rotinya di musim panas, dan mengumpulkan makanannya pada waktu panen.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 9, 'Hai pemalas, berapa lama lagi engkau berbaring? Bilakah engkau akan bangun dari tidurmu?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 10, '"Tidur sebentar lagi, mengantuk sebentar lagi, melipat tangan sebentar lagi untuk tinggal berbaring" ?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 11, 'maka datanglah kemiskinan kepadamu seperti seorang penyerbu, dan kekurangan seperti orang yang bersenjata.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 12, 'Tak bergunalah dan jahatlah orang yang hidup dengan mulut serong,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 13, 'yang mengedipkan matanya, yang bermain kaki dan menunjuk-nunjuk dengan jari,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 14, 'yang hatinya mengandung tipu muslihat, yang senantiasa merencanakan kejahatan, dan yang menimbulkan pertengkaran.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 15, 'Itulah sebabnya ia ditimpa kebinasaan dengan tiba-tiba, sesaat saja ia diremukkan tanpa dapat dipulihkan lagi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 16, 'Enam perkara ini yang dibenci TUHAN, bahkan, tujuh perkara yang menjadi kekejian bagi hati-Nya:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 17, 'mata sombong, lidah dusta, tangan yang menumpahkan darah orang yang tidak bersalah,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 18, 'hati yang membuat rencana-rencana yang jahat, kaki yang segera lari menuju kejahatan,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 19, 'seorang saksi dusta yang menyembur-nyemburkan kebohongan dan yang menimbulkan pertengkaran saudara.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 20, 'Hai anakku, peliharalah perintah ayahmu, dan janganlah menyia-nyiakan ajaran ibumu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 21, 'Tambatkanlah senantiasa semuanya itu pada hatimu, kalungkanlah pada lehermu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 22, 'Jikalau engkau berjalan, engkau akan dipimpinnya, jikalau engkau berbaring, engkau akan dijaganya, jikalau engkau bangun, engkau akan disapanya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 23, 'Karena perintah itu pelita, dan ajaran itu cahaya, dan teguran yang mendidik itu jalan kehidupan,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 24, 'yang melindungi engkau terhadap perempuan jahat, terhadap kelicikan lidah perempuan asing.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 25, 'Janganlah menginginkan kecantikannya dalam hatimu, janganlah terpikat oleh bulu matanya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 26, 'Karena bagi seorang sundal sepotong rotilah yang penting, tetapi isteri orang lain memburu nyawa yang berharga.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 27, 'Dapatkah orang membawa api dalam gelumbung baju dengan tidak terbakar pakaiannya?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 28, 'Atau dapatkah orang berjalan di atas bara, dengan tidak hangus kakinya?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 29, 'Demikian juga orang yang menghampiri isteri sesamanya; tiada seorangpun, yang menjamahnya, luput dari hukuman.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 30, 'Apakah seorang pencuri tidak akan dihina, apabila ia mencuri untuk memuaskan nafsunya karena lapar?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 31, 'Dan kalau ia tertangkap, haruslah ia membayar kembali tujuh kali lipat, segenap harta isi rumahnya harus diserahkan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 32, 'Siapa melakukan zinah tidak berakal budi; orang yang berbuat demikian merusak diri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 33, 'Siksa dan cemooh diperolehnya, malunya tidak terhapuskan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 34, 'Karena cemburu adalah geram seorang laki-laki, ia tidak kenal belas kasihan pada hari pembalasan dendam;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 6, 35, 'ia tidak akan mau menerima tebusan suatupun, dan ia akan tetap bersikeras, betapa banyakpun pemberianmu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 1, 'Hai anakku, berpeganglah pada perkataanku, dan simpanlah perintahku dalam hatimu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 2, 'Berpeganglah pada perintahku, dan engkau akan hidup; simpanlah ajaranku seperti biji matamu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 3, 'Tambatkanlah semuanya itu pada jarimu, dan tulislah itu pada loh hatimu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 4, 'Katakanlah kepada hikmat: "Engkaulah saudaraku" dan sebutkanlah pengertian itu sanakmu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 5, 'supaya engkau dilindunginya terhadap perempuan jalang, terhadap perempuan asing, yang licin perkataannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 6, 'Karena ketika suatu waktu aku melihat-lihat, dari kisi-kisiku, dari jendela rumahku,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 7, 'kulihat di antara yang tak berpengalaman, kudapati di antara anak-anak muda seorang teruna yang tidak berakal budi,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 8, 'yang menyeberang dekat sudut jalan, lalu melangkah menuju rumah perempuan semacam itu,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 9, 'pada waktu senja, pada petang hari, di malam yang gelap.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 10, 'Maka datanglah menyongsong dia seorang perempuan, berpakaian sundal dengan hati licik;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 11, 'cerewet dan liat perempuan ini, kakinya tak dapat tenang di rumah,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 12, 'sebentar ia di jalan dan sebentar di lapangan, dekat setiap tikungan ia menghadang.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 13, 'Lalu dipegangnyalah orang teruna itu dan diciumnya, dengan muka tanpa malu berkatalah ia kepadanya:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 14, '"Aku harus mempersembahkan korban keselamatan, dan pada hari ini telah kubayar nazarku itu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 15, 'Itulah sebabnya aku keluar menyongsong engkau, untuk mencari engkau dan sekarang kudapatkan engkau.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 16, 'Telah kubentangkan permadani di atas tempat tidurku, kain lenan beraneka warna dari Mesir.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 17, 'Pembaringanku telah kutaburi dengan mur, gaharu dan kayu manis.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 18, 'Marilah kita memuaskan berahi hingga pagi hari, dan bersama-sama menikmati asmara.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 19, 'Karena suamiku tidak di rumah, ia sedang dalam perjalanan jauh,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 20, 'sekantong uang dibawanya, ia baru pulang menjelang bulan purnama."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 21, 'Ia merayu orang muda itu dengan berbagai-bagai bujukan, dengan kelicinan bibir ia menggodanya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 22, 'Maka tiba-tiba orang muda itu mengikuti dia seperti lembu yang dibawa ke pejagalan, dan seperti orang bodoh yang terbelenggu untuk dihukum,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 23, 'sampai anak panah menembus hatinya; seperti burung dengan cepat menuju perangkap, dengan tidak sadar, bahwa hidupnya terancam.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 24, 'Oleh sebab itu, hai anak-anak, dengarkanlah aku, perhatikanlah perkataan mulutku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 25, 'Janganlah hatimu membelok ke jalan-jalan perempuan itu, dan janganlah menyesatkan dirimu di jalan-jalannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 26, 'Karena banyaklah orang yang gugur ditewaskannya, sangat besarlah jumlah orang yang dibunuhnya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 7, 27, 'Rumahnya adalah jalan ke dunia orang mati, yang menurun ke ruangan-ruangan maut.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 1, 'Bukankah hikmat berseru-seru, dan kepandaian memperdengarkan suaranya?', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 2, 'Di atas tempat-tempat yang tinggi di tepi jalan, di persimpangan jalan-jalan, di sanalah ia berdiri,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 3, 'di samping pintu-pintu gerbang, di depan kota, pada jalan masuk, ia berseru dengan nyaring:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 4, '"Hai para pria, kepadamulah aku berseru, kepada anak-anak manusia kutujukan suaraku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 5, 'Hai orang yang tak berpengalaman, tuntutlah kecerdasan, hai orang bebal, mengertilah dalam hatimu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 6, 'Dengarlah, karena aku akan mengatakan perkara-perkara yang dalam dan akan membuka bibirku tentang perkara-perkara yang tepat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 7, 'Karena lidahku mengatakan kebenaran, dan kefasikan adalah kekejian bagi bibirku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 8, 'Segala perkataan mulutku adalah adil, tidak ada yang belat-belit atau serong.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 9, 'Semuanya itu jelas bagi yang cerdas, lurus bagi yang berpengetahuan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 10, 'Terimalah didikanku, lebih dari pada perak, dan pengetahuan lebih dari pada emas pilihan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 11, 'Karena hikmat lebih berharga dari pada permata, apapun yang diinginkan orang, tidak dapat menyamainya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 12, 'Aku, hikmat, tinggal bersama-sama dengan kecerdasan, dan aku mendapat pengetahuan dan kebijaksanaan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 13, 'Takut akan TUHAN ialah membenci kejahatan; aku benci kepada kesombongan, kecongkakan, tingkah laku yang jahat, dan mulut penuh tipu muslihat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 14, 'Padaku ada nasihat dan pertimbangan, akulah pengertian, padakulah kekuatan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 15, 'Karena aku para raja memerintah, dan para pembesar menetapkan keadilan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 16, 'Karena aku para pembesar berkuasa juga para bangsawan dan semua hakim di bumi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 17, 'Aku mengasihi orang yang mengasihi aku, dan orang yang tekun mencari aku akan mendapatkan daku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 18, 'Kekayaan dan kehormatan ada padaku, juga harta yang tetap dan keadilan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 19, 'Buahku lebih berharga dari pada emas, bahkan dari pada emas tua, hasilku lebih dari pada perak pilihan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 20, 'Aku berjalan pada jalan kebenaran, di tengah-tengah jalan keadilan,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 21, 'supaya kuwariskan harta kepada yang mengasihi aku, dan kuisi penuh perbendaharaan mereka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 22, 'TUHAN telah menciptakan aku sebagai permulaan pekerjaan-Nya, sebagai perbuatan-Nya yang pertama-tama dahulu kala.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 23, 'Sudah pada zaman purbakala aku dibentuk, pada mula pertama, sebelum bumi ada.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 24, 'Sebelum air samudera raya ada, aku telah lahir, sebelum ada sumber-sumber yang sarat dengan air.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 25, 'Sebelum gunung-gunung tertanam dan lebih dahulu dari pada bukit-bukit aku telah lahir;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 26, 'sebelum Ia membuat bumi dengan padang-padangnya atau debu dataran yang pertama.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 27, 'Ketika Ia mempersiapkan langit, aku di sana, ketika Ia menggaris kaki langit pada permukaan air samudera raya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 28, 'ketika Ia menetapkan awan-awan di atas, dan mata air samudera raya meluap dengan deras,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 29, 'ketika Ia menentukan batas kepada laut, supaya air jangan melanggar titah-Nya, dan ketika Ia menetapkan dasar-dasar bumi,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 30, 'aku ada serta-Nya sebagai anak kesayangan, setiap hari aku menjadi kesenangan-Nya, dan senantiasa bermain-main di hadapan-Nya;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 31, 'aku bermain-main di atas muka bumi-Nya dan anak-anak manusia menjadi kesenanganku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 32, 'Oleh sebab itu, hai anak-anak, dengarkanlah aku, karena berbahagialah mereka yang memelihara jalan-jalanku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 33, 'Dengarkanlah didikan, maka kamu menjadi bijak; janganlah mengabaikannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 34, 'Berbahagialah orang yang mendengarkan daku, yang setiap hari menunggu pada pintuku, yang menjaga tiang pintu gerbangku.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 35, 'Karena siapa mendapatkan aku, mendapatkan hidup, dan TUHAN berkenan akan dia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 8, 36, 'Tetapi siapa tidak mendapatkan aku, merugikan dirinya; semua orang yang membenci aku, mencintai maut."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 1, 'Hikmat telah mendirikan rumahnya, menegakkan ketujuh tiangnya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 2, 'memotong ternak sembelihannya, mencampur anggurnya, dan menyediakan hidangannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 3, 'Pelayan-pelayan perempuan telah disuruhnya berseru-seru di atas tempat-tempat yang tinggi di kota:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 4, '"Siapa yang tak berpengalaman, singgahlah ke mari"; dan kepada yang tidak berakal budi katanya:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 5, '"Marilah, makanlah rotiku, dan minumlah anggur yang telah kucampur;', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 6, 'buanglah kebodohan, maka kamu akan hidup, dan ikutilah jalan pengertian."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 7, 'Siapa mendidik seorang pencemooh, mendatangkan cemooh kepada dirinya sendiri, dan siapa mengecam orang fasik, mendapat cela.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 8, 'Janganlah mengecam seorang pencemooh, supaya engkau jangan dibencinya, kecamlah orang bijak, maka engkau akan dikasihinya,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 9, 'berilah orang bijak nasihat, maka ia akan menjadi lebih bijak, ajarilah orang benar, maka pengetahuannya akan bertambah.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 10, 'Permulaan hikmat adalah takut akan TUHAN, dan mengenal Yang Mahakudus adalah pengertian.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 11, 'Karena oleh aku umurmu diperpanjang, dan tahun-tahun hidupmu ditambah.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 12, 'Jikalau engkau bijak, kebijakanmu itu bagimu sendiri, jikalau engkau mencemooh, engkau sendirilah orang yang akan menanggungnya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 13, 'Perempuan bebal cerewet, sangat tidak berpengalaman ia, dan tidak tahu malu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 14, 'Ia duduk di depan pintu rumahnya di atas kursi di tempat-tempat yang tinggi di kota,', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 15, 'dan orang-orang yang berlalu di jalan, yang lurus jalannya diundangnya dengan kata-kata:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 16, '"Siapa yang tak berpengalaman, singgahlah ke mari"; dan kepada orang yang tidak berakal budi katanya:', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 17, '"Air curian manis, dan roti yang dimakan dengan sembunyi-sembunyi lezat rasanya."', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 9, 18, 'Tetapi orang itu tidak tahu, bahwa di sana ada arwah-arwah dan bahwa orang-orang yang diundangnya ada di dalam dunia orang mati.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 1, 'Amsal-amsal Salomo. Anak yang bijak mendatangkan sukacita kepada ayahnya, tetapi anak yang bebal adalah kedukaan bagi ibunya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 2, 'Harta benda yang diperoleh dengan kefasikan tidak berguna, tetapi kebenaran menyelamatkan orang dari maut.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 3, 'TUHAN tidak membiarkan orang benar menderita kelaparan, tetapi keinginan orang fasik ditolak-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 4, 'Tangan yang lamban membuat miskin, tetapi tangan orang rajin menjadikan kaya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 5, 'Siapa mengumpulkan pada musim panas, ia berakal budi; siapa tidur pada waktu panen membuat malu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 6, 'Berkat ada di atas kepala orang benar, tetapi mulut orang fasik menyembunyikan kelaliman.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 7, 'Kenangan kepada orang benar mendatangkan berkat, tetapi nama orang fasik menjadi busuk.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 8, 'Siapa bijak hati, memperhatikan perintah-perintah, tetapi siapa bodoh bicaranya, akan jatuh.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 9, 'Siapa bersih kelakuannya, aman jalannya, tetapi siapa berliku-liku jalannya, akan diketahui.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 10, 'Siapa mengedipkan mata, menyebabkan kesusahan, siapa bodoh bicaranya, akan jatuh.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 11, 'Mulut orang benar adalah sumber kehidupan, tetapi mulut orang fasik menyembunyikan kelaliman.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 12, 'Kebencian menimbulkan pertengkaran, tetapi kasih menutupi segala pelanggaran.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 13, 'Di bibir orang berpengertian terdapat hikmat, tetapi pentung tersedia bagi punggung orang yang tidak berakal budi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 14, 'Orang bijak menyimpan pengetahuan, tetapi mulut orang bodoh adalah kebinasaan yang mengancam.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 15, 'Kota yang kuat bagi orang kaya ialah hartanya, tetapi yang menjadi kebinasaan bagi orang melarat ialah kemiskinan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 16, 'Upah pekerjaan orang benar membawa kepada kehidupan, penghasilan orang fasik membawa kepada dosa.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 17, 'Siapa mengindahkan didikan, menuju jalan kehidupan, tetapi siapa mengabaikan teguran, tersesat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 18, 'Siapa menyembunyikan kebencian, dusta bibirnya; siapa mengumpat adalah orang bebal.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 19, 'Di dalam banyak bicara pasti ada pelanggaran, tetapi siapa yang menahan bibirnya, berakal budi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 20, 'Lidah orang benar seperti perak pilihan, tetapi pikiran orang fasik sedikit nilainya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 21, 'Bibir orang benar menggembalakan banyak orang, tetapi orang bodoh mati karena kurang akal budi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 22, 'Berkat Tuhanlah yang menjadikan kaya, susah payah tidak akan menambahinya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 23, 'Berlaku cemar adalah kegemaran orang bebal, sebagaimana melakukan hikmat bagi orang yang pandai.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 24, 'Apa yang menggentarkan orang fasik, itulah yang akan menimpa dia, tetapi keinginan orang benar akan diluluskan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 25, 'Bila taufan melanda, lenyaplah orang fasik, tetapi orang benar adalah alas yang abadi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 26, 'Seperti cuka bagi gigi dan asap bagi mata, demikian si pemalas bagi orang yang menyuruhnya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 27, 'Takut akan TUHAN memperpanjang umur, tetapi tahun-tahun orang fasik diperpendek.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 28, 'Harapan orang benar akan menjadi sukacita, tetapi harapan orang fasik menjadi sia-sia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 29, 'Jalan TUHAN adalah perlindungan bagi orang yang tulus, tetapi kebinasaan bagi orang yang berbuat jahat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 30, 'Orang benar tidak terombang-ambing untuk selama-lamanya, tetapi orang fasik tidak akan mendiami negeri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 31, 'Mulut orang benar mengeluarkan hikmat, tetapi lidah bercabang akan dikerat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 10, 32, 'Bibir orang benar tahu akan hal yang menyenangkan, tetapi mulut orang fasik hanya tahu tipu muslihat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 1, 'Neraca serong adalah kekejian bagi TUHAN, tetapi Ia berkenan akan batu timbangan yang tepat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 2, 'Jikalau keangkuhan tiba, tiba juga cemooh, tetapi hikmat ada pada orang yang rendah hati.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 3, 'Orang yang jujur dipimpin oleh ketulusannya, tetapi pengkhianat dirusak oleh kecurangannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 4, 'Pada hari kemurkaan harta tidak berguna, tetapi kebenaran melepaskan orang dari maut.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 5, 'Jalan orang saleh diratakan oleh kebenarannya, tetapi orang fasik jatuh karena kefasikannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 6, 'Orang yang jujur dilepaskan oleh kebenarannya, tetapi pengkhianat tertangkap oleh hawa nafsunya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 7, 'Pengharapan orang fasik gagal pada kematiannya, dan harapan orang jahat menjadi sia-sia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 8, 'Orang benar diselamatkan dari kesukaran, lalu orang fasik menggantikannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 9, 'Dengan mulutnya orang fasik membinasakan sesama manusia, tetapi orang benar diselamatkan oleh pengetahuan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 10, 'Bila orang benar mujur, beria-rialah kota, dan bila orang fasik binasa, gemuruhlah sorak-sorai.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 11, 'Berkat orang jujur memperkembangkan kota, tetapi mulut orang fasik meruntuhkannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 12, 'Siapa menghina sesamanya, tidak berakal budi, tetapi orang yang pandai, berdiam diri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 13, 'Siapa mengumpat, membuka rahasia, tetapi siapa yang setia, menutupi perkara.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 14, 'Jikalau tidak ada pimpinan, jatuhlah bangsa, tetapi jikalau penasihat banyak, keselamatan ada.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 15, 'Sangat malanglah orang yang menanggung orang lain, tetapi siapa membenci pertanggungan, amanlah ia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 16, 'Perempuan yang baik hati beroleh hormat; sedangkan seorang penindas beroleh kekayaan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 17, 'Orang yang murah hati berbuat baik kepada diri sendiri, tetapi orang yang kejam menyiksa badannya sendiri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 18, 'Orang fasik membuat laba yang sia-sia, tetapi siapa menabur kebenaran, mendapat pahala yang tetap.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 19, 'Siapa berpegang pada kebenaran yang sejati, menuju hidup, tetapi siapa mengejar kejahatan, menuju kematian.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 20, 'Orang yang serong hatinya adalah kekejian bagi TUHAN, tetapi orang yang tak bercela, jalannya dikenan-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 21, 'Sungguh, orang jahat tidak akan luput dari hukuman, tetapi keturunan orang benar akan diselamatkan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 22, 'Seperti anting-anting emas di jungur babi, demikianlah perempuan cantik yang tidak susila.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 23, 'Keinginan orang benar mendatangkan bahagia semata-mata, harapan orang fasik mendatangkan murka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 24, 'Ada yang menyebar harta, tetapi bertambah kaya, ada yang menghemat secara luar biasa, namun selalu berkekurangan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 25, 'Siapa banyak memberi berkat, diberi kelimpahan, siapa memberi minum, ia sendiri akan diberi minum.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 26, 'Siapa menahan gandum, ia dikutuki orang, tetapi berkat turun di atas kepala orang yang menjual gandum.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 27, 'Siapa mengejar kebaikan, berusaha untuk dikenan orang, tetapi siapa mengejar kejahatan akan ditimpa kejahatan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 28, 'Siapa mempercayakan diri kepada kekayaannya akan jatuh; tetapi orang benar akan tumbuh seperti daun muda.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 29, 'Siapa yang mengacaukan rumah tangganya akan menangkap angin; orang bodoh akan menjadi budak orang bijak.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 30, 'Hasil orang benar adalah pohon kehidupan, dan siapa bijak, mengambil hati orang.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 11, 31, 'Kalau orang benar menerima balasan di atas bumi, lebih-lebih orang fasik dan orang berdosa!', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 1, 'Siapa mencintai didikan, mencintai pengetahuan; tetapi siapa membenci teguran, adalah dungu.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 2, 'Orang baik dikenan TUHAN, tetapi si penipu dihukum-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 3, 'Orang tidak akan tetap tegak karena kefasikan, tetapi akar orang benar tidak akan goncang.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 4, 'Isteri yang cakap adalah mahkota suaminya, tetapi yang membuat malu adalah seperti penyakit yang membusukkan tulang suaminya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 5, 'Rancangan orang benar adalah adil, tujuan orang fasik memperdaya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 6, 'Perkataan orang fasik menghadang darah, tetapi mulut orang jujur menyelamatkan orang.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 7, 'Orang fasik dijatuhkan sehingga mereka tidak ada lagi, tetapi rumah orang benar berdiri tetap.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 8, 'Setiap orang dipuji seimbang dengan akal budinya, tetapi orang yang serong hatinya, akan dihina.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 9, 'Lebih baik menjadi orang kecil, tetapi bekerja untuk diri sendiri, dari pada berlagak orang besar, tetapi kekurangan makan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 10, 'Orang benar memperhatikan hidup hewannya, tetapi belas kasihan orang fasik itu kejam.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 11, 'Siapa mengerjakan tanahnya, akan kenyang dengan makanan, tetapi siapa mengejar barang yang sia-sia, tidak berakal budi.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 12, 'Orang fasik mengingini jala orang jahat, tetapi akar orang benar mendatangkan hasil.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 13, 'Orang jahat terjerat oleh pelanggaran bibirnya, tetapi orang benar dapat keluar dari kesukaran.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 14, 'Setiap orang dikenyangkan dengan kebaikan oleh karena buah perkataan, dan orang mendapat balasan dari pada yang dikerjakan tangannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 15, 'Jalan orang bodoh lurus dalam anggapannya sendiri, tetapi siapa mendengarkan nasihat, ia bijak.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 16, 'Bodohlah yang menyatakan sakit hatinya seketika itu juga, tetapi bijak, yang mengabaikan cemooh.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 17, 'Siapa mengatakan kebenaran, menyatakan apa yang adil, tetapi saksi dusta menyatakan tipu daya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 18, 'Ada orang yang lancang mulutnya seperti tikaman pedang, tetapi lidah orang bijak mendatangkan kesembuhan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 19, 'Bibir yang mengatakan kebenaran tetap untuk selama-lamanya, tetapi lidah dusta hanya untuk sekejap mata.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 20, 'Tipu daya ada di dalam hati orang yang merencanakan kejahatan, tetapi orang yang menasihatkan kesejahteraan mendapat sukacita.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 21, 'Orang benar tidak akan ditimpa oleh bencana apapun, tetapi orang fasik akan senantiasa celaka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 22, 'Orang yang dusta bibirnya adalah kekejian bagi TUHAN, tetapi orang yang berlaku setia dikenan-Nya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 23, 'Orang yang bijak menyembunyikan pengetahuannya, tetapi hati orang bebal menyeru-nyerukan kebodohan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 24, 'Tangan orang rajin memegang kekuasaan, tetapi kemalasan mengakibatkan kerja paksa.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 25, 'Kekuatiran dalam hati membungkukkan orang, tetapi perkataan yang baik menggembirakan dia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 26, 'Orang benar mendapati tempat penggembalaannya, tetapi jalan orang fasik menyesatkan mereka sendiri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 27, 'Orang malas tidak akan menangkap buruannya, tetapi orang rajin akan memperoleh harta yang berharga.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 12, 28, 'Di jalan kebenaran terdapat hidup, tetapi jalan kemurtadan menuju maut.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 1, 'Anak yang bijak mendengarkan didikan ayahnya, tetapi seorang pencemooh tidak mendengarkan hardikan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 2, 'Dari buah mulutnya seseorang akan makan yang baik, tetapi nafsu seorang pengkhianat ialah melakukan kelaliman.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 3, 'Siapa menjaga mulutnya, memelihara nyawanya, siapa yang lebar bibir, akan ditimpa kebinasaan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 4, 'Hati si pemalas penuh keinginan, tetapi sia-sia, sedangkan hati orang rajin diberi kelimpahan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 5, 'Orang benar benci kepada dusta, tetapi orang fasik memalukan dan memburukkan diri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 6, 'Kebenaran menjaga orang yang saleh jalannya, tetapi kefasikan mencelakakan orang berdosa.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 7, 'Ada orang yang berlagak kaya, tetapi tidak mempunyai apa-apa, ada pula yang berpura-pura miskin, tetapi hartanya banyak.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 8, 'Kekayaan adalah tebusan nyawa seseorang, tetapi orang miskin tidak akan mendengar ancaman.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 9, 'Terang orang benar bercahaya gemilang, sedangkan pelita orang fasik padam.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 10, 'Keangkuhan hanya menimbulkan pertengkaran, tetapi mereka yang mendengarkan nasihat mempunyai hikmat.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 11, 'Harta yang cepat diperoleh akan berkurang, tetapi siapa mengumpulkan sedikit demi sedikit, menjadi kaya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 12, 'Harapan yang tertunda menyedihkan hati, tetapi keinginan yang terpenuhi adalah pohon kehidupan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 13, 'Siapa meremehkan firman, ia akan menanggung akibatnya, tetapi siapa taat kepada perintah, akan menerima balasan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 14, 'Ajaran orang bijak adalah sumber kehidupan, sehingga orang terhindar dari jerat-jerat maut.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 15, 'Akal budi yang baik mendatangkan karunia, tetapi jalan pengkhianat-pengkh mencelakakan mereka.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 16, 'Orang cerdik bertindak dengan pengetahuan, tetapi orang bebal membeberkan kebodohan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 17, 'Utusan orang fasik menjerumuskan orang ke dalam celaka, tetapi duta yang setia mendatangkan kesembuhan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 18, 'Kemiskinan dan cemooh menimpa orang yang mengabaikan didikan, tetapi siapa mengindahkan teguran, ia dihormati.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 19, 'Keinginan yang terlaksana menyenangkan hati, menghindari kejahatan adalah kekejian bagi orang bebal.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 20, 'Siapa bergaul dengan orang bijak menjadi bijak, tetapi siapa berteman dengan orang bebal menjadi malang.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 21, 'Orang berdosa dikejar oleh malapetaka, tetapi Ia membalas orang benar dengan kebahagiaan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 22, 'Orang baik meninggalkan warisan bagi anak cucunya, tetapi kekayaan orang berdosa disimpan bagi orang benar.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 23, 'Huma orang miskin menghasilkan banyak makanan, tetapi ada yang lenyap karena tidak ada keadilan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 24, 'Siapa tidak menggunakan tongkat, benci kepada anaknya; tetapi siapa mengasihi anaknya, menghajar dia pada waktunya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 13, 25, 'Orang benar makan sekenyang-kenyangnya, tetapi perut orang fasik menderita kekurangan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 1, 'Perempuan yang bijak mendirikan rumahnya, tetapi yang bodoh meruntuhkannya dengan tangannya sendiri.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 2, 'Siapa berjalan dengan jujur, takut akan TUHAN, tetapi orang yang sesat jalannya, menghina Dia.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 3, 'Di dalam mulut orang bodoh ada rotan untuk punggungnya, tetapi orang bijak dipelihara oleh bibirnya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 4, 'Kalau tidak ada lembu, juga tidak ada gandum, tetapi dengan kekuatan sapi banyaklah hasil.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 5, 'Saksi yang setia tidak berbohong, tetapi siapa menyembur-nyemburkan kebohongan, adalah saksi dusta.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 6, 'Si pencemooh mencari hikmat, tetapi sia-sia, sedangkan bagi orang berpengertian, pengetahuan mudah diperoleh.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 7, 'Jauhilah orang bebal, karena pengetahuan tidak kaudapati dari bibirnya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 8, 'Mengerti jalannya sendiri adalah hikmat orang cerdik, tetapi orang bebal ditipu oleh kebodohannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 9, 'Orang bodoh mencemoohkan korban tebusan, tetapi orang jujur saling menunjukkan kebaikan.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 10, 'Hati mengenal kepedihannya sendiri, dan orang lain tidak dapat turut merasakan kesenangannya.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 11, 'Rumah orang fasik akan musnah, tetapi kemah orang jujur akan mekar.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 12, 'Ada jalan yang disangka orang lurus, tetapi ujungnya menuju maut.', 'id', 'TB'),
  ('20', 'ams', 'Amsal', 14, 13, 'Di dalam tertawapun hati dapat merana, dan kesukaan dapat berakhir dengan kedukaan.', 'id', 'TB'),
